/** Error body produced by ErrorResponseFactory: an RFC 9457 Problem Details object served as application/problem+json, which also keeps the legacy members (timestamp, error, code). With app.errors.problem-details.enabled=false only the legacy members are sent, as application/json. Some handlers add extension members (errors, budget, upstreamStatus, lockedReason ...); the gateway's own 401 may carry an empty body. */
export interface ErrorBody {
  [key: string]: unknown;
  /** Stable, machine-readable problem type, e.g. urn:vegaduta:problem:agent-not-found. Branch on this, not on the message. Absent when problem details are switched off. */
  type?: string;
  /** HTTP reason phrase of the status. */
  title?: string;
  /** HTTP status code, repeated from the status line. */
  status: number;
  /** Human-readable explanation; same text as error. */
  detail?: string;
  /** Request path the problem occurred on (never the query string). */
  instance?: string;
  timestamp?: string;
  /** Human-readable message (legacy member). */
  error: string;
  /** Stable machine-readable code, present only on handlers that disambiguate with one. */
  code?: string;
  /** Correlation id, equal to the X-Request-Id response header. */
  requestId?: string;
  /** OpenTelemetry trace id, when tracing is on. */
  traceId?: string;
}

